// Pass every ContaGen row through, and emit the unique domain set for the Supersoniq stage.
const rows = $input.all().map(i => i.json);
const domains = [];
const seen = new Set();
for (const r of rows) {
  const d = String(r.Domain || r.domain || r.company_domain || '').trim().toLowerCase();
  if (d && !seen.has(d)) { seen.add(d); domains.push(d); }
}
return [{ json: { _domains: domains, _domain_count: domains.length, _row_count: rows.length } }];

const g = $('Launch Guard').first().json;
const t = (n) => ({ name: n, type: 'singleLineText' });
const sel = (n, ch) => ({ name: n, type: 'singleSelect', options: { choices: ch.map(c=>({ name: c })) } });
const fields = [
  t('Name'), t('Contact Key'), t('first_name'), t('last_name'), t('Title'),
  sel('Seniority', ['C-Suite','Founder','Owner','President','Executive','VP','Head','Director','Manager','Senior','Partner','EVP / SVP','Board / Chair','Unclassified']),
  sel('Department', ['Executive','Engineering','Technology','R&D','Product','Data','Security','Design','Operations','Sales','Marketing','Finance','Human Resources','Customer Success','Project Management','Strategy','Legal','Supply Chain','Communications','Community & Social','Compliance & GRC']),
  t('Email'), t('Social'), t('Phone'), t('Connections'), t('Domain'), t('Company'), t('Industry Groups'),
  sel('Employees', ['1-10','11-50','51-200','201-500','501-1000','1001-5000','5001-10000','10001+']),
  t('Business Model'), t('MX Provider'),
  t('Description'), t('Keywords'), t('City'), t('State'), t('Country'), t('Zip'), t('Street'),
  sel('Contact Source', ['ContaGen','Supersoniq']),
  t('Tag')
];

const coreNames = new Set(fields.map(f => f.name));
// Operator ruling 2026-08-12. These never enter a contacts table, by contract or by CSV header.
// company_clean: cleaning happens on Company itself. State Full: State is the only location column.
// Valid / Start Date / Redirect Domain / Update Date: CSV noise, they were never contract entries.
// Seniority Rank, Run ID, Build Date, Source, MV: owned elsewhere or retired.
// Extra CSV columns are still welcome. This list is the standard, not a lock.
const skip = new Set(['domain','company_domain','Verified','segment','query_name','ingested_at','RankInCompany',
  'company_clean','State Full','Score','Similarity','Valid','Start Date','Redirect Domain','Update Date',
  'Run ID','Seniority Rank','Build Date','Source','MV','Tag']);
const seenExtra = new Set();
const csvRows = $('Read CSV').all().map(i => i.json);
for (const r of csvRows) {
  for (const k of Object.keys(r)) {
    if (coreNames.has(k) || skip.has(k) || seenExtra.has(k)) continue;
    seenExtra.add(k);
    fields.push(t(k));
  }
}

const formulaFields = [
  { name: 'Build Date', type: 'formula', options: { formula: 'CREATED_TIME()' } }
];
const desiredName = (g.buildName || 'List') + ' - Contacts';
return [{ json: { mode: g.mode, existingTableId: g.existingTableId, buildNameIgnored: !!g.buildNameIgnored, desiredName, fields, formulaFields } }];

const titleCase=(s)=>String(s).replace(/\w\S*/g,t=>t.charAt(0).toUpperCase()+t.slice(1).toLowerCase());
const cleanFirst=(f)=>{if(!f)return'';let n=String(f).split(',')[0].trim().split(/\s+/)[0]||'';n=n.replace(/[^A-Za-z\-']/g,'');return n?n.charAt(0).toUpperCase()+n.slice(1).toLowerCase():'';};
const cleanLast=(f)=>{if(!f)return'';let p=String(f).split(',')[0].trim().split(/\s+/);if(p.length<2)return'';return titleCase(p.slice(1).join(' ').replace(/[^A-Za-z\-'\s]/g,'').trim());};
const cleanCompany=(nm)=>{if(!nm)return'';const orig=String(nm).trim();let c=orig;
const GEN=new Set(['home','welcome','shop','store','about','about us','products','index','page','contact','contact us','blog','news']);
const isGen=(s)=>GEN.has(String(s).trim().toLowerCase());
const pick=(a)=>{for(const p of a){if(p&&String(p).trim()&&!isGen(p))return String(p).trim();}return null;};
c=c.replace(/^welcome to\s+/i,'').trim();
const pp=c.split(' | '); if(pp.length>1){const s=pick(pp); if(s===null) return orig; c=s;}
for(let i=0;i<2;i++){const d=c.search(/\s[-–—]\s/); if(d<3) break; const head=c.slice(0,d).trim(); const tail=c.slice(d).replace(/^\s[-–—]\s/,'').trim(); const s=pick([head,tail]); if(s===null) return orig; c=s;}
if(/^[A-Za-z0-9][A-Za-z0-9-]*(\.[A-Za-z]{2,})+$/.test(c)) c=c.replace(/(\.[A-Za-z]{2,})+$/,'');
c=c.replace(/[®™]/g,'');
for(let i=0;i<2;i++){c=c.replace(/[,\s]+(inc|llc|l\.l\.c\.|ltd|limited|corp|corporation|co|company|gmbh|plc|llp|lp|pllc|pc)\.?$/i,'').trim();}
c=c.replace(/,+$/,'').trim();
const hasUp=/\p{Lu}/u.test(c), hasLow=/\p{Ll}/u.test(c);
if(hasUp!==hasLow){const parts=c.split(/(\s+)/); const words=parts.filter(t=>/\S/.test(t)); const MINOR=new Set(['of','and','the','for','to','in','on','at','by','a','an']);
if(!(hasUp&&words.length===1&&c.length<=4)){let wi=-1; c=parts.map(t=>{if(!/\S/.test(t))return t; wi++; const lw=t.toLowerCase(); return (wi>0&&MINOR.has(lw))?lw:lw.replace(/\p{L}/u,(ch)=>ch.toUpperCase());}).join('');}}
return c;};
const ST={AL:'Alabama',AK:'Alaska',AZ:'Arizona',AR:'Arkansas',CA:'California',CO:'Colorado',CT:'Connecticut',DE:'Delaware',FL:'Florida',GA:'Georgia',HI:'Hawaii',ID:'Idaho',IL:'Illinois',IN:'Indiana',IA:'Iowa',KS:'Kansas',KY:'Kentucky',LA:'Louisiana',ME:'Maine',MD:'Maryland',MA:'Massachusetts',MI:'Michigan',MN:'Minnesota',MS:'Mississippi',MO:'Missouri',MT:'Montana',NE:'Nebraska',NV:'Nevada',NH:'New Hampshire',NJ:'New Jersey',NM:'New Mexico',NY:'New York',NC:'North Carolina',ND:'North Dakota',OH:'Ohio',OK:'Oklahoma',OR:'Oregon',PA:'Pennsylvania',RI:'Rhode Island',SC:'South Carolina',SD:'South Dakota',TN:'Tennessee',TX:'Texas',UT:'Utah',VT:'Vermont',VA:'Virginia',WA:'Washington',WV:'West Virginia',WI:'Wisconsin',WY:'Wyoming',DC:'District of Columbia',PR:'Puerto Rico',ON:'Ontario',QC:'Quebec',BC:'British Columbia',AB:'Alberta',MB:'Manitoba',SK:'Saskatchewan',NS:'Nova Scotia',NB:'New Brunswick'};
const FULL=new Set(Object.values(ST).map(v=>v.toLowerCase()));
const stateFull=(raw)=>{if(raw==null)return'';let s=String(raw).trim();if(!s)return'';let u=s.toUpperCase().replace(/\./g,'');if(ST[u])return ST[u];if(FULL.has(s.toLowerCase()))return titleCase(s);return s;};

const rows=$('Read CSV').all().map(i=>i.json);

const RESERVED=new Set(['Name','Domain','domain','company_domain','Email','Verified','Company','State','first_name','last_name','company_clean','State Full','segment','query_name','ingested_at','Run ID','RankInCompany','Contact Source','Build Date','Tag']);
const ROW_ONLY=new Set(['Title','Seniority','Department','Social','Phone','Connections','Similarity']);
const COMPANY_COLS=['Business Model','MX Provider'];

const cmap={};
for(const r of rows){
  const d=String(r.Domain||r.domain||r.company_domain||'').trim().toLowerCase();
  if(!d) continue;
  const c=cmap[d]||(cmap[d]={});
  for(const k of Object.keys(r)){
    if(RESERVED.has(k)||ROW_ONLY.has(k)) continue;
    const v=r[k];
    if((c[k]===undefined||c[k]==='') && v!==undefined && String(v).trim()!=='') c[k]=String(v).trim();
  }
  for(const k of COMPANY_COLS){ if(c[k]===undefined) c[k]=''; }
}

const runId=String($execution.id);
const tag=((($('Waterfall Upload').first().json['Tag'])||'')+'').trim();
const _st=($('Config').first().json||{}).startedAt;
let buildDate='';
try{ buildDate=DateTime.fromISO(String(_st)).toFormat('yyyy-MM-dd'); }catch(e){ buildDate=''; }
if(!buildDate||buildDate==='Invalid DateTime'){ buildDate=$now.toFormat('yyyy-MM-dd'); }
let skipped=0;
const out=[];
for(const r of rows){
  const name=String(r.Name||'').trim();
  const domain=String(r.Domain||r.domain||'').trim().toLowerCase();
  const first=cleanFirst(name);
  const last=cleanLast(name);
  const key=(first.toLowerCase().trim()+last.toLowerCase().trim()+domain).trim();
  if(!key){ skipped++; continue; }
  if(!name) continue;
  const co=cmap[domain]||{};

  const passthrough={};
  for(const k of Object.keys(r)){
    if(RESERVED.has(k)) continue;
    const v=r[k];
    passthrough[k]=(v===undefined||v===null)?'':String(v).trim();
  }
  for(const k of Object.keys(co)){
    if(co[k]!==undefined && co[k]!=='') passthrough[k]=co[k];
  }

  out.push({json:{
    ...passthrough,
    'Contact Key':key,
    Name:name,
    first_name:first,
    last_name:last,
    Domain:domain,
    Company:cleanCompany(co.Company||String(r.Company||'').trim()),
    company_clean:cleanCompany(co.Company||r.Company),
    State:co.State||String(r.State||'').trim(),
    'State Full':stateFull(co.State||r.State||''),
    'Business Model':co['Business Model']||'',
    'MX Provider':co['MX Provider']||'',
    Email:String(r.Email||'').trim(),
    'Run ID':runId,
    'Build Date':buildDate,
    'Tag':tag,
    'Contact Source':'ContaGen'
  }});
}
const sd=$getWorkflowStaticData('global');
sd.wfSkips=sd.wfSkips||{cg:0,sq:0};
sd.wfSkips.cg=skipped;
return out;

const form = $('Waterfall Upload').first().json;
const domains = ($('Parse Domains').first().json._domains) || [];
const asArr = (v, def) => { if (v===undefined||v===null||v==='') return def; if (Array.isArray(v)) return v.map(x=>String(x).trim()).filter(Boolean); return String(v).split(',').map(s=>s.trim()).filter(Boolean); };
const CMAP={'United States':'US','Israel':'IL','United Kingdom':'GB','Canada':'CA','Australia':'AU','Germany':'DE','France':'FR','Netherlands':'NL'};
const seniority = asArr(form['Seniority levels (default net pre-ticked; untick to narrow)'], ['C-Suite','Founder','Owner','President','VP','Head','Director']);
const depts = asArr(form['Target departments'], ['ALL']);
const locNames = asArr(form['Contact location'], ['United States']);
const loc = locNames.map(x=>CMAP[x]||x);
const perCo = parseInt(form['Contacts per company'], 10) || 5;
const filters = { seniority, contact_countries: loc };
if (!(depts.length===0 || depts.map(d=>String(d).toUpperCase()).includes('ALL'))) { filters.function = depts; }
const chunks = [];
for (let i=0; i<domains.length; i+=1000) { chunks.push(domains.slice(i, i+1000)); }
if (!chunks.length) return [];
return chunks.map(c => ({ json: { companies: c.map(d=>({domain:d})), filters, per_company_limit: perCo, tier: 'full' } }));

