const form=$('Waterfall Upload').first().json;
const g=$('Contacts Table Guard').first().json||{};
const cg=$('Format ContaGen').all().length;
const sqNew=$('Format Supersoniq').all().length;
const total=cg+sqNew;
const domains=($('Parse Domains').first().json._domain_count)||0;
let matched=0,delivered=0,credits=0;
for(const i of $('SQ Enrich').all()){const r=i.json||{};matched+=(r.companies_matched||0);delivered+=(r.contacts_delivered||0);credits+=(r.credits_used||0);}
const overlaps=Math.max(0,delivered-sqNew);
const noContact=Math.max(0,domains-matched);
const sd=$getWorkflowStaticData('global');
const sk=sd.wfSkips||{cg:0,sq:0};
const skipped=(Number(sk.cg)||0)+(Number(sk.sq)||0);
const tableName=g.tableName||'';
const tableId=g.tableId||'';
const modeTxt=(g.mode==='append')?'appended to an existing table':'created a new table';
const fc=(g.fieldsCreated&&g.fieldsCreated.length)?g.fieldsCreated.join(', '):'none';
const tag=((form['Tag']||'')+'').trim();
const trig=form._launchRecordId?'record':'form';
const started=form.submittedAt||($('Config').first().json||{}).startedAt;
let dur=0; try{ if(started)dur=Math.max(0,Math.round(($now.toMillis()-new Date(started).getTime())/1000)); }catch(e){}
const errors=g.createdFieldError?1:0;
const fmt=v=>Number(v||0).toLocaleString('en-US');
const parts=[];
parts.push('**'+fmt(total)+' contacts upserted across '+fmt(domains)+' domains**');
parts.push('**Tag:** '+(tag||'none'));
parts.push('**Sources**\n- **ContaGen:** '+fmt(cg)+' contacts\n- **Supersoniq:** '+fmt(sqNew)+' net-new ('+fmt(delivered)+' delivered, '+fmt(overlaps)+' overlapped with ContaGen)');
parts.push('**Domains**\n- **Supersoniq matched:** '+fmt(matched)+'\n- **No contact found:** '+fmt(noContact));
parts.push('**Credits spent:** '+fmt(credits)+'\n**Rows skipped (empty Contact Key):** '+fmt(skipped));
parts.push('**Table:** '+modeTxt+', '+tableName+' ('+tableId+')\n**Fields created:** '+fc);
const warns=[];
if(g.createdFieldError){ warns.push('- '+g.createdFieldError); }
if(g.buildNameIgnored){ warns.push('- Build name ignored: an Existing Table ID was supplied.'); }
if(warns.length){ parts.push('**Warnings ('+warns.length+')**\n'+warns.join('\n')); }
parts.push('**Launched via:** '+trig);
return [{ json: {
  'Automation': 'Contagen -> Supersoniq -> Clayroots',
  'Status': errors?'Succeeded with errors':'Succeeded',
  'Trigger': 'form',
  'Errors': errors,
  'Run at': $now.toISO(),
  'Client': form['Clayroots Base ID'],
  'Target': tableName+' ('+tableId+')',
  'Records In': cg,
  'Records Out': total,
  'Duration s': dur,
  'Description': parts.join('\n\n'),
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + $workflow.id + '/executions/' + $execution.id,
  'Execution ID': String($execution.id)
} }];

const items=$input.all();
for(const i of items){const r=i.json||{};
  if(r.success===false){ throw new Error('Supersoniq enrich failed: '+(r.error||r.detail||r.message||'request error')); }
  if(r.credits_remaining!==undefined && Number(r.credits_remaining)<=0){ throw new Error('Supersoniq credits exhausted mid-run (credits_remaining<=0) - table left partial, failing loud.'); }
}
return items;

// Attach the resolved Client record link to the Build Log payload, then hand it to Log Run.
// The upsert payload is ALWAYS the Build Log fields; Resolve Client only contributes the link.
// When no client resolves, the Client key is DELETED (never emitted empty) so the upsert
// leaves the launch row's existing Client link untouched.
const log = { ...$('Build Log').first().json };
const items = $input.all();
const rec = items.length ? (items[0].json || {}) : {};
const clientId = (typeof rec.id === 'string' && rec.id.startsWith('rec')) ? rec.id : '';
if (clientId) { log.Client = [clientId]; } else { delete log.Client; }
if (!log['Execution ID']) { throw new Error('Fix Client: Build Log payload has no Execution ID. Log row not written.'); }
return [{ json: log }];

const rec=$('Fetch Launch Record').first().json;
const f=rec.fields||{};
const client=$('Resolve Base').first().json;
const cf=client.fields||{};
const arr=v=>Array.isArray(v)?v:(v?[v]:[]);
const sen=arr(f['Seniority']);
const dep=arr(f['Departments']);
const loc=arr(f['Country']);
const att=(f['Attachment']||[])[0]||{};
if(!att.url){ throw new Error('Launch record '+rec.id+' has no Attachment CSV.'); }
const tid = (((f['Table ID']||'')+'').trim()) || (((f['Target']||'')+'').trim());
return [{ json: {
  'Clayroots Base ID': ((cf['Clayroots Base ID']||'')+'').trim(),
  'Build name': ((f['Build name']||'')+'').trim(),
  'Existing Table ID': tid,
  'Tag': ((f['Tag']||'')+'').trim(),
  'ContaGen contacts CSV': { filename: att.filename||'launch.csv', mimetype: att.type||'text/csv' },
  'Seniority levels (default net pre-ticked; untick to narrow)': sen.length?sen:['C-Suite','Founder','Owner','President','VP','Head','Director'],
  'Target departments': dep.length?dep:['ALL'],
  'Contacts per company': f['Contacts per company']||5,
  'Contact location': loc.length?loc:['United States'],
  '_launchRecordId': rec.id,
  'submittedAt': new Date().toISOString()
} }];

const params=$('Launch Params').first().json;
const bin=$input.first().binary||{};
const data=bin.data||Object.values(bin)[0];
if(!data){ throw new Error('Download CSV returned no binary data.'); }
return [{ json: params, binary: { 'ContaGen_contacts_CSV': data } }];

const form = $('Waterfall Upload').first().json;
const build = ((form['Build name'] || '') + '').trim();
const tid = ((form['Existing Table ID'] || '') + '').trim();
if (!build && !tid) { throw new Error('Provide a Build name (to create a new table) or an Existing Table ID (to append to one). Nothing was written.'); }
if (tid && !/^tbl[A-Za-z0-9]{14}$/.test(tid)) { throw new Error('Existing Table ID "' + tid + '" is not a valid Airtable table id (expected tbl followed by 14 characters). Nothing was written.'); }
const sd = $getWorkflowStaticData('global');
sd.wfSkips = { cg: 0, sq: 0 };
const bin = $input.first().binary || {};
return [{ json: { buildName: build, existingTableId: tid, mode: tid ? 'append' : 'create', buildNameIgnored: !!(tid && build) }, binary: bin }];

const spec = $('Build Table Schema').first().json;
const baseId = (($('Waterfall Upload').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT List Tables').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not read the table list for base ' + baseId + ': ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const plain = spec.fields || [];
const formulas = spec.formulaFields || [];
if (spec.mode !== 'append') {
  const taken = new Set(tables.map(t => String(t.name)));
  let name = spec.desiredName; let n = 1;
  while (taken.has(name)) { n++; name = spec.desiredName + ' (' + n + ')'; }
  return [{ json: { mode: 'create', createName: name, fields: plain, missing: [], missingNames: [], formulaNames: formulas.map(f => f.name), buildNameIgnored: false } }];
}
const target = tables.find(t => t.id === spec.existingTableId);
if (!target) { throw new Error('Table ' + spec.existingTableId + ' does not exist in base ' + baseId + '. Tables there: ' + tables.map(t => t.name).join(', ') + '. Nothing was written.'); }
if (/domains/i.test(String(target.name || ''))) { throw new Error("Refusing to write contacts into '" + target.name + "' - that table is a domains table. Nothing was written."); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const targetFields = target.fields || [];
const existing = new Map(targetFields.map(f => [f.name, f]));
const existingCI = new Map(targetFields.map(f => [norm(f.name), f]));
const COMPUTED = new Set(formulas.map(f => f.name));
const kind = (ty) => ty === 'number' ? 'number' : (ty === 'singleSelect' ? 'select' : (ty === 'date' ? 'date' : 'text'));
const okWith = { number: ['number'], text: ['singleLineText','multilineText','singleSelect'], select: ['singleSelect','singleLineText'], date: ['date','dateTime'] };
const contract = plain.concat(formulas);
const clashes = []; const missing = [];
for (const cf of contract) {
  if (COMPUTED.has(cf.name)) {
    const exc = existingCI.get(norm(cf.name));
    if (!exc) { missing.push(cf); continue; }
    if (exc.type !== 'formula') { throw new Error("Table '" + target.name + "' (" + target.id + ') still has a writable ' + cf.name + ' (type: ' + exc.type + '). Convert it to a CREATED_TIME() formula field before building. Nothing was written.'); }
    continue;
  }
  const ex = existing.get(cf.name);
  if (!ex) { missing.push(cf); continue; }
  if (!okWith[kind(cf.type)].includes(ex.type)) { clashes.push(cf.name + ' (type in table: ' + ex.type + ', type expected: ' + cf.type + ')'); }
}
if (clashes.length) { throw new Error("Type clash in table '" + target.name + "' (" + target.id + '): ' + clashes.join('; ') + '. Nothing was written.'); }
const pf = targetFields[0] || {};
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, primaryFieldName: pf.name || '', hasContactKey: existing.has('Contact Key'), fields: contract, missing, missingNames: missing.map(f => f.name), formulaNames: formulas.map(f => f.name), buildNameIgnored: !!spec.buildNameIgnored } }];

const r = $('Table Router').first().json;
let rows = [];
try { rows = $('AT Read Contacts').all().map(i => i.json || {}).filter(x => x && x.id); } catch (e) { rows = []; }
const n = rows.length >= 100 ? '100+' : String(rows.length);
if (!r.hasContactKey && rows.length > 0) { throw new Error("Target table '" + r.tableName + "' has " + n + " rows but no Contact Key column. Appending contacts here would duplicate instead of dedupe. Nothing was written."); }
return [{ json: Object.assign({}, r, { fieldsCreated: [], rowsProbed: n }) }];

const r = $('Table Router').first().json;
const baseId = (($('Waterfall Upload').first().json['Clayroots Base ID'])||'').trim();
const resp = $('AT Verify Schema').first().json || {};
const tables = Array.isArray(resp.tables) ? resp.tables : null;
if (!tables) { throw new Error('Could not re-read the schema of base ' + baseId + ' after creating fields: ' + JSON.stringify(resp).slice(0,400) + '. Nothing was written.'); }
const target = tables.find(t => t.id === r.tableId);
if (!target) { throw new Error('Table ' + r.tableId + ' is no longer present in base ' + baseId + '. Nothing was written.'); }
const norm = (s) => String(s == null ? '' : s).trim().toLowerCase();
const targetFields = target.fields || [];
const have = new Set(targetFields.map(f => f.name));
const haveCI = new Set(targetFields.map(f => norm(f.name)));
const COMPUTED = new Set(r.formulaNames || []);
const SOFT = new Set(['Seniority Rank']);
const present = (n) => COMPUTED.has(n) ? haveCI.has(norm(n)) : have.has(n);
const still = (r.fields || []).filter(f => !SOFT.has(f.name) && !present(f.name)).map(f => f.name);
if (still.length) { throw new Error("Could not create these fields on '" + target.name + "' (" + target.id + '): ' + still.join(', ') + '. Nothing was written.'); }
const wanted = r.missingNames || [];
const created = wanted.filter(n => present(n));
return [{ json: { mode: 'append', tableId: target.id, tableName: target.name, fieldsCreated: created, buildNameIgnored: !!r.buildNameIgnored, createdFieldError: '' } }];

const j = $input.first().json || {};
const baseId = (($('Waterfall Upload').first().json['Clayroots Base ID'])||'').trim();
if (!j.id) { throw new Error('Airtable table creation failed in base ' + baseId + ': ' + JSON.stringify(j).slice(0,400)); }
return [{ json: { mode: 'create', tableId: j.id, tableName: j.name, fieldNames: (j.fields || []).map(f => f.name) } }];

const j = $input.first().json || {};
if (j && j.mode === 'append') {
  if (!j.tableId) { throw new Error('Table resolution returned no table id: ' + JSON.stringify(j).slice(0,400)); }
  return [{ json: { tableId: j.tableId, tableName: j.tableName, mode: 'append', fieldsCreated: j.fieldsCreated || [], buildNameIgnored: !!j.buildNameIgnored, createdFieldError: j.createdFieldError || '' } }];
}
const ct = $('Created Table Guard').first().json || {};
const fieldsCreated = (ct.fieldNames || []).slice();
return [{ json: { tableId: ct.tableId, tableName: ct.tableName, mode: 'create', fieldsCreated, buildNameIgnored: false, createdFieldError: '' } }];

// Write-boundary standard, Operator ruling 2026-08-12. Removes everything retired from the contract
// so the payload can never resurrect a banned column or 422 on a fresh table that lacks it:
// Build Date (computed), Run ID (retired), company_clean (cleaning lives on Company itself),
// Score / Similarity / Valid / Start Date / Redirect Domain / Update Date (CSV noise, banned),
// State Full folds into State (full name wins), Source maps to Contact Source (provenance).
const BAN=['Build Date','Run ID','company_clean','Score','Similarity','Valid','Start Date','Redirect Domain','Update Date','MV'];
return $input.all().map(i => { const j = { ...i.json };
  if(j['State Full']!==undefined){ if(String(j['State Full']||'').trim()) j['State']=j['State Full']; delete j['State Full']; }
  if(Object.prototype.hasOwnProperty.call(j,'Source')){ if(j['Contact Source']===undefined) j['Contact Source']=j.Source; delete j.Source; }
  for(const k of BAN) delete j[k];
  return { json: j }; });

